export const meta = {
  name: "per-key-rate-limit",
  description: "Per-API-key token buckets, refill capped at capacity, integer Retry-After on 429",
  phases: [
    { name: "propose", detail: "Each worker proposes a plan without seeing the others" },
    { name: "challenge", detail: "Each worker argues against the other proposals, authors hidden" },
    { name: "decide", detail: "Judge picks or joins the best plan and fixes the task" },
    { name: "build", detail: "Worker implements the single task" },
    { name: "cross-review", detail: "A worker who did not build it reviews; findings go back to build" },
    { name: "sign-off", detail: "Judge checks the done criteria" },
  ],
};

const TASK = "per-key-bucket";
const request = args.request;
const workerCount = Math.max(1, Number(args.crew?.worker) || 1);

const goal = `Request: ${request}

Context from the repo (already read):
- ratelimit/bucket.py: TokenBucket(capacity, rate, clock). allow() adds elapsed*rate tokens with NO cap at capacity, then takes one token. There is one bucket per middleware instance.
- ratelimit/middleware.py: limit(handler, capacity, rate, clock) wraps one shared bucket and returns {"status": 429, "headers": {}, "body": "too many requests"} when rejected.
- tests/test_middleware.py and tests/test_bucket.py exist. The currently failing rate-limiter test is in tests/test_bucket.py (it checks that refills are capped at capacity).

Required behaviour:
1. Each X-Api-Key header value gets its own TokenBucket. Requests without an X-Api-Key header share one bucket. Match the header name case-insensitively.
2. Token refill is capped at capacity (tokens = min(capacity, tokens + elapsed*rate)).
3. A rejected request gets HTTP 429 with a Retry-After header whose value is a whole number of seconds (integer, rounded up) until a token is available. Add a method on TokenBucket to report that wait so the middleware can compute it.
4. Done means: the currently failing rate-limiter test passes, all existing tests still pass, and the 429 response includes an integer-seconds Retry-After header.
Work only in this repository. Keep the existing code style and comment density.`;

const planSchema = {
  type: "object",
  properties: { plan: { type: "string" } },
  required: ["plan"],
};

phase("propose");
const proposals = await parallel(
  Array.from({ length: workerCount }, (_, i) => () =>
    agent(
      `${goal}

Propose a concrete implementation plan for this change: which files to touch, the bucket-per-key design, how the wait time is computed, how the cap is applied, and how the tests will be run. Do not edit any files. Reply in the plan field.`,
      { role: "worker", model: i, access: "read", label: `propose:p${i + 1}`, phase: "propose", schema: planSchema }
    )
  )
);
const plans = proposals.filter(Boolean).map((p) => p.plan);

phase("challenge");
const challenges = await parallel(
  Array.from({ length: workerCount }, (_, i) => () =>
    agent(
      `${goal}

Here are the candidate plans (authors are hidden):
${plans.map((p, j) => `--- Plan ${j + 1} ---\n${p}`).join("\n\n")}

Argue against these plans. Name the concrete risks, missed requirements, and weak spots in each. Do not edit any files. Reply in the critique field.`,
      {
        role: "worker",
        model: i,
        access: "read",
        label: `challenge:c${i + 1}`,
        phase: "challenge",
        schema: { type: "object", properties: { critique: { type: "string" } }, required: ["critique"] },
      }
    )
  )
);
const critiques = challenges.filter(Boolean).map((c) => c.critique);

phase("decide");
const decision = await agent(
  `${goal}

Candidate plans:
${plans.map((p, j) => `--- Plan ${j + 1} ---\n${p}`).join("\n\n")}

Critiques:
${critiques.map((c, j) => `--- Critique ${j + 1} ---\n${c}`).join("\n\n")}

Pick the strongest plan or join the best parts of them. This request is one piece of work, so produce exactly one task named "${TASK}". Reply with the chosen plan as text in plan, and the list of concrete done checks in done.`,
  {
    role: "judge",
    access: "read",
    label: "decide:judge",
    phase: "decide",
    schema: {
      type: "object",
      properties: { plan: { type: "string" }, done: { type: "array", items: { type: "string" } } },
      required: ["plan", "done"],
    },
  }
);

if (!decision) {
  log("Decide step returned no answer; stopping before build.");
} else {
  const doneList = (decision.done || []).join("\n- ");
  const reviewSchema = {
    type: "object",
    properties: { accept: { type: "boolean" }, findings: { type: "array", items: { type: "string" } } },
    required: ["accept", "findings"],
  };

  let accepted = false;
  let findings = [];
  let lastReview = null;

  // One build plus at most 2 sends back: 3 builds in total.
  for (let round = 0; round <= 2; round++) {
    phase("build");
    const built = await agent(
      `${goal}

Chosen plan:
${decision.plan}

Done checks:
- ${doneList}

${findings.length ? `Your previous try was sent back by the reviewer. Fix these findings and carry on from your existing change:\n- ${findings.join("\n- ")}\n` : ""}Implement the change in the repository and run the test suite. Reply with a short summary of what you changed and the test output.`,
      { role: "worker", task: TASK, label: `build:per-key`, phase: "build" }
    );
    if (!built) {
      log(`Build round ${round + 1} returned no answer.`);
      continue;
    }

    phase("cross-review");
    const review = await agent(
      `${goal}

Chosen plan:
${decision.plan}

Done checks:
- ${doneList}

Review the change made on this task. Check it against the requirements and done checks, run the test suite yourself, and do not edit any files. Set accept to true only if every requirement and done check holds. Otherwise list each concrete finding in findings.`,
      {
        role: "worker",
        notTheAuthor: true,
        access: "read",
        task: TASK,
        label: `review:per-key`,
        phase: "cross-review",
        schema: reviewSchema,
      }
    );
    if (!review) {
      log(`Review round ${round + 1} returned no answer.`);
      continue;
    }
    lastReview = review;
    if (review.accept) {
      accepted = true;
      break;
    }
    findings = review.findings || [];
  }

  const holds = await check(
    "The currently failing rate-limiter test passes, all existing tests pass, and the 429 response includes an integer-seconds Retry-After header.",
    { task: TASK }
  );

  phase("sign-off");
  const signOff = await agent(
    `${goal}

Check that the work on task "${TASK}" meets the done checks:
- ${doneList}

Reviewer accepted: ${accepted}
Reviewer findings still open: ${lastReview && !accepted ? (lastReview.findings || []).join("; ") || "none listed" : "none"}
Check result: ${holds && holds.holds ? "holds" : "does not hold: " + ((holds && holds.failed) || "unknown")}

Run the tests yourself and do not edit any files. Reply with approved true or false and notes explaining anything that is still open. If the work was not accepted by its reviewers, report their findings to the user in notes.`,
    {
      role: "judge",
      access: "read",
      label: "signoff:judge",
      phase: "sign-off",
      schema: {
        type: "object",
        properties: { approved: { type: "boolean" }, notes: { type: "string" } },
        required: ["approved", "notes"],
      },
    }
  );

  if (signOff) log(`Sign-off approved=${signOff.approved}: ${signOff.notes}`);
  else log("Sign-off returned no answer.");
}

// Not run by this script: the follow-up "/workflow try spec-first" with the same request is a separate command.

